    "tsx": "4.19.3",
    "pino-pretty": "13.0.0"
  }
}

import { Worker } from 'bullmq'
import IORedis from 'ioredis'
import pino from 'pino'

const logger = pino({
  level: process.env['LOG_LEVEL'] ?? 'info',
  ...(process.env['NODE_ENV'] === 'development' && {
    transport: { target: 'pino-pretty', options: { colorize: true } },
  }),
})

/**
 * IORedis connection for BullMQ.
 *
 * REQUIRED: maxRetriesPerRequest must be null for BullMQ.
 * Uses REDIS_PRIVATE_URL (Railway internal DNS) in production.
 */
const redisUrl = process.env['REDIS_PRIVATE_URL']
if (!redisUrl) {
  logger.fatal('REDIS_PRIVATE_URL is required — worker cannot start without Redis')
  process.exit(1)
}

const connection = new IORedis(redisUrl, {
  maxRetriesPerRequest: null,
  enableReadyCheck: false,
  lazyConnect: true,
})

connection.on('connect', () => logger.info('redis connected'))
connection.on('error', (err) => logger.error({ err }, 'redis error'))

/**
 * BullMQ worker — processes jobs from the inkos-jobs queue.
 *
 * Add job handlers below as sprints ship new features.
 * Each handler is a separate file in src/handlers/.
 */
const worker = new Worker(
  'inkos-jobs',
  async (job) => {
    const log = logger.child({ jobId: job.id, name: job.name, attempt: job.attemptsMade + 1 })
    log.info('processing job')

    switch (job.name) {
      case 'send-email':
        log.info('send-email — Sprint 1')
        break
      case 'generate-consent-pdf':
        log.info('generate-consent-pdf — Sprint 5')
        break
      case 'process-ai-design':
        log.info('process-ai-design — Sprint 9')
        break
      case 'send-booking-reminder':
        log.info('send-booking-reminder — Sprint 2')
        break
      case 'generate-payroll':
        log.info('generate-payroll — Sprint 8')
        break
      case 'sync-calendar':
        log.info('sync-calendar — Sprint 11')
        break
      case 'generate-1099k':
        log.info('generate-1099k — Sprint 8')
        break
      default:
        throw new Error(`Unknown job: ${job.name}`)
    }
  },
  {
    connection,
    concurrency: 5,
    limiter: { max: 100, duration: 60_000 },
  }
)

worker.on('completed', (job) => {
  logger.info({ jobId: job.id, name: job.name }, 'job completed')
})

worker.on('failed', (job, err) => {
  logger.error({ err, jobId: job?.id, name: job?.name, attempt: job?.attemptsMade }, 'job failed')
})

worker.on('error', (err) => {
  logger.error({ err }, 'worker error')
})

logger.info({ queue: 'inkos-jobs', concurrency: 5 }, 'worker started')

/**
 * Graceful shutdown on SIGTERM (Railway sends this before stopping the container).
 */
async function shutdown(signal: string) {
  logger.info({ signal }, 'shutting down worker gracefully')
  await worker.close()
  await connection.quit()
  process.exit(0)
}

process.on('SIGTERM', () => void shutdown('SIGTERM'))
process.on('SIGINT', () => void shutdown('SIGINT'))

