import cron from 'node-cron'
import { Queue } from 'bullmq'
import IORedis from 'ioredis'
import pino from 'pino'

const logger = pino({
  level: process.env['LOG_LEVEL'] ?? 'info',
  ...(process.env['NODE_ENV'] === 'development' && {
    transport: { target: 'pino-pretty', options: { colorize: true } },
  }),
})

const redisUrl = process.env['REDIS_PRIVATE_URL']
if (!redisUrl) {
  logger.fatal('REDIS_PRIVATE_URL is required — cron worker cannot start')
  process.exit(1)
}

const connection = new IORedis(redisUrl, {
  maxRetriesPerRequest: null,
  enableReadyCheck: false,
})

const jobsQueue = new Queue('inkos-jobs', { connection })

/**
 * Cron schedules — add new jobs as sprints ship features.
 *
 * All times are UTC. Adjust per studio timezone in the job handler itself.
 */

// Booking reminders — every 15 minutes
cron.schedule('*/15 * * * *', async () => {
  logger.info('cron: enqueueing booking reminders check')
  // Sprint 2: enqueue per-booking reminder jobs
})

// Daily summary — 8:00 AM UTC
cron.schedule('0 8 * * *', async () => {
  logger.info('cron: enqueueing daily summary')
  // Sprint 1: enqueue per-studio daily summary jobs
})

// Monthly payroll — 1st of month, 9:00 AM UTC
cron.schedule('0 9 1 * *', async () => {
  logger.info('cron: enqueueing monthly payroll run')
  // Sprint 8: query all studios and enqueue generate-payroll jobs
})

// Yearly 1099-K — January 15, 10:00 AM UTC
cron.schedule('0 10 15 1 *', async () => {
  logger.info('cron: enqueueing 1099-K generation')
  // Sprint 8: enqueue generate-1099k jobs for prior year
})

// Revoke expired guest artist access — daily at 1:00 AM UTC
cron.schedule('0 1 * * *', async () => {
  logger.info('cron: checking for expired guest artist engagements')
  // Sprint 10: query expired guest_artist_engagements and revoke access
})

// Inactive client check — weekly Sunday 2:00 AM UTC
cron.schedule('0 2 * * 0', async () => {
  logger.info('cron: enqueueing inactive client emails')
  // Sprint 11: enqueue marketing automation jobs
})

logger.info('cron worker started')

async function shutdown(signal: string) {
  logger.info({ signal }, 'shutting down cron worker')
  await jobsQueue.close()
  await connection.quit()
  process.exit(0)
}

process.on('SIGTERM', () => void shutdown('SIGTERM'))
process.on('SIGINT', () => void shutdown('SIGINT'))

# InkOS — Rollback Procedures

## Automated Rollback (Railway)

Railway automatically rolls back if the healthcheck fails after deploy.

**Trigger:** `GET /api/health` returns 503 or times out (100s timeout)
**Action:** Railway reverts to the previous successful deployment automatically

## Manual Rollback (Bolt runs this)

### Web Service Rollback
```bash
# List recent deployments
railway deployments --service web

# Roll back to a specific deployment
railway rollback --deployment DEPLOYMENT_ID --service web

# Or roll back to previous deployment
railway rollback --service web
```

### Database Migration Rollback

Migrations are tracked in `supabase/migrations/`. To roll back:

```sql
-- Sprint 0 rollback (run in Supabase SQL editor)
-- WARNING: This deletes all data in these tables

-- 1. Drop triggers first
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
DROP TRIGGER IF EXISTS profiles_updated_at ON public.profiles;
DROP TRIGGER IF EXISTS studios_updated_at ON public.studios;
DROP TRIGGER IF EXISTS studio_members_updated_at ON public.studio_members;
DROP TRIGGER IF EXISTS locations_updated_at ON public.locations;
DROP TRIGGER IF EXISTS subscriptions_updated_at ON public.subscriptions;

-- 2. Drop functions
DROP FUNCTION IF EXISTS auth.user_studio_ids();
DROP FUNCTION IF EXISTS public.handle_new_user();
DROP FUNCTION IF EXISTS public.handle_updated_at();

-- 3. Drop tables in reverse FK order
DROP TABLE IF EXISTS public.webhook_events;
DROP TABLE IF EXISTS public.audit_log;
DROP TABLE IF EXISTS public.subscriptions;
DROP TABLE IF EXISTS public.locations;
DROP TABLE IF EXISTS public.studio_members;
DROP TABLE IF EXISTS public.studios;
DROP TABLE IF EXISTS public.profiles;
DROP TABLE IF EXISTS public._health;
```

## Emergency Contacts

- Railway status: https://status.railway.app
- Supabase status: https://status.supabase.com
- Dodo Payments status: https://status.dodopayments.com

## Sprint Rollback Guide

Each sprint adds a new migration. Rolling back a sprint means:
1. Roll back Railway deployment to pre-sprint deploy
2. Execute the sprint's DOWN migration SQL (written by Dato alongside each migration)
3. Update DNS if domain changes were made

Specific DOWN migrations will be added by Dato for each sprint.

